@register('limits','slowly-varying-tridiagonal-determinant','locally-Toeplitz-determinant-limit','block-cutting-and-uniform-spectral-control','A determinant grows with its dimension and its coefficients vary across the matrix. Cutting into mesoscopic blocks and controlling the logarithmic determinant error converts a local recurrence root into a Riemann integral.','The Hilbert moment determinant uses an exact global product and logarithmic energy. Here no exact global determinant formula is supplied; uniform spectral bounds make a local approximation valid.',[{'caseId':'profile-'+str(i),'bernstein':a,'purpose':'Different nonconstant positive profiles change interior coefficient geometry; reversal duplicates are excluded.'} for i,a in enumerate([[0,1,2],[0,2,1],[1,0,3],[0,1,0,2],[1,3,0,1],[0,0,2,3],[2,0,1,3],[0,1,2,0,3],[1,0,3,1,2],[0,3,0,2,1],[2,1,0,3,4],[1,2,4,0,3]])],['positive definite matrices','tridiagonal determinant recurrence','logarithmic determinant perturbation bounds','Riemann sums'])
def local_toeplitz(case):
 a=case['bernstein'];d=len(a)-1;g=s.expand(1+sum(v*s.binomial(d,j)*x**j*(1-x)**(d-j) for j,v in enumerate(a)));average=s.integrate(g,(x,0,1));A=s.exp(average);lam=s.symbols('lambda',positive=True)
 ck('Bernstein basis integrates to a uniform coefficient average',average,1+R(sum(a),d+1));condition('Uniform positivity follows from nonnegative Bernstein coefficients',min(a)>=0,'The Bernstein basis is nonnegative and sums to one on the unit interval, so g is at least1.')
 D0=s.Integer(1);D1=lam+1/lam
 for N in range(1,7):
  if N==1:D=D1
  else:D=(lam+1/lam)*D1-D0;D0,D1=D1,s.expand(D)
  ck('Exact constant-block determinant recurrence at size '+str(N),s.cancel(D),(lam**(N+1)-lam**(-N-1))/(lam-lam**-1))
 analytic('Mesoscopic block approximation',['The displayed polynomial g is at least1 on the unit interval and has bounded derivative. All matrices and block approximations are real symmetric.'],['Gershgorin gives a common positive lower eigenvalue bound delta=2cosh(1)-2 and a common finite upper bound M for every matrix used below.','Partition into blocks of length floor(sqrt n), remove links between blocks, and freeze each block diagonal at one point. Removing links changes rank by O(sqrt n). Relative eigenvalues stay between delta/M and M/delta, so the logarithmic determinant changes by O(sqrt n).','Freezing diagonals changes operator norm by O(n^(-1/2)); along the positive definite straight-line path, integrate trace(A inverse times A prime) to bound the log determinant error by O(sqrt n).','For a block with diagonal2cosh u, the exact recurrence gives determinant sinh((m+1)u)/sinh u. Since u>=1, its logarithm is m*u+O(1), uniformly.','Divide the sum of block logarithms by n. All errors vanish, and the main terms form a Riemann sum for integral0to1 g. Exponentiation gives the limit.'])
 return candidate(r'g(x)='+L(g)+r'.'+T('For each positive integer n, let A be the n by n real tridiagonal matrix with ')+r'A_{jj}=2\cosh(g(j/n))\ (1\le j\le n),\qquad A_{j,j+1}=A_{j+1,j}=1,'+T('and all other entries zero. Determine ')+r'\lim_{n\to\infty}(\det A)^{1/n}.',A,[(s.exp(g.subs(x,0)),'Freeze every diagonal at the left endpoint'),(s.exp(g.subs(x,1)),'Freeze every diagonal at the right endpoint'),(s.exp(2*average),'Square the growing characteristic root'),(s.exp(average/2),'Take a spurious square root of the determinant growth'),(s.exp(average-1),'Omit the constant baseline in the coefficient profile'),(s.exp(g.subs(x,R(1,2))),'Replace the whole Riemann average by one midpoint sample')],[T('All coefficient profiles are uniformly above the spectral edge. In particular, a common positive lower bound for every eigenvalue is ')+r'\delta=2\cosh1-2>0.',T('Cut the matrix into blocks of about square-root n rows and freeze the diagonal in each block. The removed links have total rank of order square-root n; the freezing error has operator norm of order inverse square-root n.'),r'\frac1n\left|\ln\det A-\sum_B\ln\det A_B^{\mathrm{constant}}\right|\longrightarrow0',T('The rank bound follows from uniform relative-eigenvalue bounds. The small-norm bound follows by integrating the trace formula for the derivative of a logarithmic determinant.'),T('For a constant block with diagonal ')+r'2\cosh u'+T(' and adjacent off-diagonal entries one, let ')+r'D_m'+T(' denote its determinant when its size is ')+r'm'+T(' by ')+r'm'+T('.'),r'D_0=1,\quad D_1=2\cosh u,\quad D_m=2\cosh u\,D_{m-1}-D_{m-2}=\frac{\sinh((m+1)u)}{\sinh u}',r'\ln D_m=mu+O(1)\quad(u\ge1)',r'\frac1n\ln\det A\longrightarrow\int_0^1g(x)\,\mathrm dx='+L(average)],'varying-tridiagonal-logdet-mesoscopic-block-limit')

@register('limits','rank-one-outlier-edge','rank-one-secular-limit-with-edge-threshold','determinant-lemma-and-monotone-Stieltjes-limit','A low-rank perturbation of a growing diagonal matrix has one possible outlier. The secular equation must be identified, its edge threshold checked, and the finite root trapped before passing to a Riemann integral.','This is neither a fixed-matrix perturbation derivative nor a trace average: the largest eigenvalue is selected through a nonlinear limiting spectral equation.',[{'caseId':'weight-'+str(p)+'-root-'+str(r),'p':p,'root':str(r),'purpose':'Different vanishing powers of the perturbing vector and dimensionless outlier gaps.'} for p in [1,2,3] for r in [R(5,4),R(3,2),2,3]],['rank-one determinant lemma','symmetric eigenvalues','monotone Riemann sums','spectral edge control'])
def outlier(case):
 p=case['p'];r=R(case['root']);a=r-1;I=s.simplify(sum((-a)**j/R(p-j) for j in range(p))+(-a)**p*s.log(r/a));weight=1/I;A=r
 ck('Independent integral evaluation of the secular kernel',s.integrate((1-x)**p/(r-x),(x,0,1)),I)
 condition('The prescribed limiting root is strictly above the diagonal edge',r>1 and p>=1,'The kernel is positive and strictly smaller than its value at the edge; hence the chosen coupling is strictly above the threshold p.')
 for N in [2,3]:
  D=s.diag(*[R(j,N) for j in range(N)]);v=s.Matrix([(1-R(j,N))**R(p,2) for j in range(N)]);rho=s.symbols('rho');h=s.symbols('h');M=rho*s.eye(N)-D;exact=s.factor((M-h*v*v.T/N).det());secular=s.prod(rho-R(j,N) for j in range(N))*(1-h/N*sum((1-R(j,N))**p/(rho-R(j,N)) for j in range(N)));ck('Finite determinant lemma checked directly at dimension '+str(N),s.cancel(exact),s.cancel(secular))
 analytic('Outlier convergence above the edge',['The perturbation coupling is positive; the vector coordinates are positive because the diagonal grid stops before1.','The chosen rational target exceeds1, and the power is a positive integer.'],['The determinant lemma makes the unique eigenvalue above the largest diagonal entry solve1=(lambda/n)sum(1-j/n)^p/(rho-j/n). The right side is strictly decreasing from infinity to zero on that interval.','For any rho>1 the sum converges to I_p(rho)=integral0to1(1-t)^p/(rho-t)dt, locally uniformly away from1. At the edge its limiting value is1/p, while it strictly decreases to zero at infinity.','The specified lambda=1/I_p(r) exceeds p, so the limiting equation has the unique root r>1. Choose two fixed points just below and above r, still above1; strict monotonicity and Riemann convergence trap the finite roots between them for all large n.','As the two trapping points approach r, the largest eigenvalue converges to r. All remaining eigenvalues lie below this one by the monotone secular equation or rank-one interlacing.'])
 pool=[(1,'Ignore the detached eigenvalue and retain the diagonal spectral edge'),(1+(r-1)*p/(p+1),'Use the unweighted mass normalization for the outlier gap'),(1+(r-1)*(p+1)/p,'Invert the vanishing-weight normalization for the gap'),(1+(r-1)**2,'Square the gap rather than the perturbing-vector coordinates'),(r*r,'Return a squared spectral location'),(1+(r-1)/2,'Halve the detached gap when passing from a quadratic form to an eigenvalue'),(1+2*(r-1),'Double the detached gap by counting both rank-one matrix factors')]
 return candidate(r'\lambda='+L(weight)+r'.'+T('For positive integers n, define a real symmetric matrix ')+r'A_n=\operatorname{diag}(0,1/n,\ldots,(n-1)/n)+\frac\lambda n vv^{\mathsf T},\qquad v_j=(1-j/n)^{'+L(R(p,2))+r'}\ (0\le j<n).'+T('Find the limit of the largest eigenvalue of ')+r'A_n.',A,pool,[T('Above the largest diagonal entry, the determinant lemma gives the strictly decreasing secular equation.'),r'1=\frac\lambda n\sum_{j=0}^{n-1}\frac{(1-j/n)^{'+str(p)+r'}}{\rho-j/n}',r'I(\rho)=\int_0^1\frac{(1-t)^{'+str(p)+r'}}{\rho-t}\,\mathrm dt,\qquad I(1+)=\frac1{'+str(p)+r'},\qquad I\prime(\rho)<0\quad(\rho>1)',r'I('+L(r)+r')='+L(I)+r'=\frac1\lambda',T('The selected coupling is above the edge threshold because the displayed integral is strictly smaller than its edge value. Thus the limiting equation has the unique root shown, separated from the edge.'),T('The finite sums converge at any two fixed points on opposite sides of that root. Their monotonicity traps the finite largest eigenvalue between those points. Shrinking the bracket proves convergence.')],'growing-diagonal-rank-one-detached-eigenvalue-limit')

@register('limits','lacunary-Fourier-moment','lacunary-Fourier-zero-frequency-pairings','base-digit-cancellation-and-leading-pair-partitions','An oscillatory high moment is evaluated by identifying which frequency combinations survive integration. The large base rules out carries, and only pair partitions contribute at the highest order in the number of terms.','Quadratic Weyl equidistribution controls oscillatory averages by differencing. Here an exact finite zero-frequency combinatorics selects a Gaussian moment without invoking a central limit theorem.',[{'caseId':'even-moment-'+str(r),'r':r,'base':2*r+1,'purpose':'Different even moment orders change the pairing geometry and exact limiting moment; the base is fixed minimally for the proof at each order.'} for r in range(2,14)],['Fourier orthogonality','integer base expansions','pair partitions','polynomial leading coefficients'])
def lacunary(case):
 r=case['r'];b=case['base'];A=s.factorial(2*r)/(4**r*s.factorial(r));base=[R(1,4**j*s.factorial(j)**2) for j in range(r+1)]
 # The constant-term counts for n frequencies are polynomial in n, degree r.
 coeff=[s.Integer(1)]+[s.Integer(0)]*r;values=[s.Integer(0)]
 for N in range(1,r+1):
  coeff=[sum(coeff[j]*base[k-j] for j in range(k+1)) for k in range(r+1)];values.append(s.factorial(2*r)*coeff[r])
 diff=sum((-1)**(r-j)*s.binomial(r,j)*values[j] for j in range(r+1));ck('Independent finite-difference extraction of the leading constant-term count',diff/s.factorial(r),A)
 ck('The pair-partition count including cosine normalization',s.factorial(2*r)/(2**r*s.factorial(r))*R(1,2)**r,A)
 condition('No nonzero balanced digit can carry to the next frequency',b>2*r,'Any signed occurrence count has absolute value at most2r; reducing a zero frequency sum modulo the base forces its lowest digit to vanish, then induction forces all digits to vanish.')
 analytic('Exact Fourier balance and highest-order pairings',['The base is an integer larger than the total number2r of selected cosine factors. Integrals are over a complete angular period.'],['Expand each cosine as the sum of two exponentials divided by2. Orthogonality kills every term with nonzero total frequency.','If sum d_k*b^k=0 with integers|d_k|<=2r<b, reducing modulo b and repeating forces all d_k=0. Thus each selected frequency occurs with equally many plus and minus signs.','At most r different frequencies can occur. Terms with fewer than r different frequencies number O(n^(r-1)), with constants depending only on r.','The leading terms use exactly r different frequencies, each twice with opposite signs. Choose the frequencies, distribute their two occurrences among the2r positions and choose the two signs. After the cosine factor2^(-2r), the leading coefficient is(2r)!/(4^r r!).'])
 return candidate(r'S_n(x)=\frac1{\sqrt n}\sum_{k=0}^{n-1}\cos('+str(b)+r'^kx).'+T('Evaluate ')+r'\lim_{n\to\infty}\frac1{2\pi}\int_0^{2\pi}S_n(x)^{'+str(2*r)+r'}\,\mathrm dx.',A,[(s.factorial(2*r)/(2**r*s.factorial(r)),'Forget that a cosine has variance one half'),(s.factorial(2*r)/(8**r*s.factorial(r)),'Apply the cosine variance factor twice'),(s.factorial(2*r)/4**r,'Treat unordered selected frequency pairs as ordered'),(s.factorial(2*r)/(4**r*s.factorial(r)**2),'Divide a second time for the choice of frequency pairs'),(s.binomial(2*r,r)/4**r,'Use a single repeated frequency instead of r distinct frequencies'),(s.factorial(2*r)/(4**r*s.factorial(r-1)),'Select only r minus one frequency-pair labels')],[r'\cos('+str(b)+r'^kx)=\frac12\left(e^{i'+str(b)+r'^kx}+e^{-i'+str(b)+r'^kx}\right)',T('Integration over the full period retains exactly zero total frequency. A balanced base expansion with all digits smaller in magnitude than the base must have every digit zero.'),r'\sum_kd_k'+str(b)+r'^k=0,\quad|d_k|\le'+str(2*r)+r'<'+str(b)+r'\quad\Longrightarrow\quad d_k=0\ \textnormal{for every }k',T('The leading terms therefore use exactly '+str(r)+' distinct frequencies, twice each, once with each sign. Terms using fewer distinct frequencies contribute a lower-degree count.'),r'\frac1{2\pi}\int_0^{2\pi}\left(\sum_{k=0}^{n-1}\cos('+str(b)+r'^kx)\right)^{'+str(2*r)+r'}\mathrm dx=\binom n{'+str(r)+r'}\frac{'+str(2*r)+r'!}{2^{'+str(2*r)+r'}}+O(n^{'+str(r-1)+r'})',r'\frac{\binom n{'+str(r)+r'}}{n^{'+str(r)+r'}}\longrightarrow\frac1{'+str(r)+r'!}'],'lacunary-Fourier-even-moment-exact-leading-pairings')

